#include <stdio.h>
int main(){
    int payload=2980, mtu=1500, header=20, max_data=mtu-header;
    int remaining=payload, offset=0;
    while(remaining>0){
        int data = remaining>max_data?max_data:remaining;
        int total = data+header;
        printf("Fragment: Length=%d bytes, Offset=%d, MF=%d\n", total, offset/8, (remaining-data)>0);
        remaining -= data;
        offset += data;
    }
    return 0;
}
